#!/usr/bin/env bash
# Compares azalea-rs/azalea with this fork and writes a Markdown report of what
# upstream has that the fork doesn't, and whether it merges or rebases cleanly.
#
# Checked: upstream's main against the fork's main, and upstream's newest
# version branch (like 26.3) against the fork's branch of the same name.
#
# Run from a full clone of the fork with its branches fetched as origin/*.
# Writes the report to $REPORT and sets `changed=true|false` in
# $GITHUB_OUTPUT (when set). Never pushes anything.
set -euo pipefail

UPSTREAM_URL=${UPSTREAM_URL:-https://github.com/azalea-rs/azalea.git}
UPSTREAM_WEB=${UPSTREAM_WEB:-https://github.com/azalea-rs/azalea}
REPORT=${REPORT:-upstream-report.md}
# At most this many commits are listed per branch.
MAX_LISTED=${MAX_LISTED:-50}

git remote get-url upstream >/dev/null 2>&1 || git remote add upstream "$UPSTREAM_URL"
git fetch --quiet --no-tags upstream \
	'+refs/heads/*:refs/remotes/upstream/*'

# The newest version branch, ordered as versions (1.21.11 < 26.1 < 26.3).
newest_version=$(git for-each-ref --format='%(refname:lstrip=3)' refs/remotes/upstream/ |
	grep -E '^[0-9]+(\.[0-9]+)+$' | sort -V | tail -n1 || true)

pairs=("main:main")
[[ -n $newest_version ]] && pairs+=("$newest_version:$newest_version")

changed=false
{
	echo "<!-- upstream-watch: generated by .github/workflows/upstream-watch.yml -->"
	echo "Upstream ([azalea-rs/azalea]($UPSTREAM_WEB)) has commits this fork doesn't."
	echo "Nothing has been merged or pushed; this is a report only."
	echo
} >"$REPORT"

# Prints the conflicting paths of the merge or rebase in progress, as a list.
conflicts() {
	git diff --name-only --diff-filter=U | sed 's/^/  - `/; s/$/`/'
}

for pair in "${pairs[@]}"; do
	up=${pair%%:*}
	ours=${pair#*:}
	up_ref=refs/remotes/upstream/$up
	our_ref=refs/remotes/origin/$ours

	if ! git rev-parse --verify --quiet "$our_ref" >/dev/null; then
		changed=true
		{
			echo "## \`$up\`"
			echo
			echo "Upstream has a \`$up\` branch ([\`$(git rev-parse --short "$up_ref")\`]($UPSTREAM_WEB/commit/$(git rev-parse "$up_ref"))) and this fork has no branch of that name."
			echo
		} >>"$REPORT"
		continue
	fi

	count=$(git rev-list --count "$our_ref..$up_ref")
	[[ $count -eq 0 ]] && continue
	changed=true

	{
		echo "## upstream \`$up\` → fork \`$ours\`"
		echo
		echo "$count new upstream commit(s), up to [\`$(git rev-parse --short "$up_ref")\`]($UPSTREAM_WEB/commit/$(git rev-parse "$up_ref")):"
		echo
		git log --no-merges --format="- [\`%h\`]($UPSTREAM_WEB/commit/%H) %s (%an, %as)" \
			-n "$MAX_LISTED" "$our_ref..$up_ref"
		[[ $count -gt $MAX_LISTED ]] &&
			echo "- … and more: $UPSTREAM_WEB/compare/$(git rev-parse --short "$our_ref")...$(git rev-parse --short "$up_ref")"
		echo
	} >>"$REPORT"

	# A test merge of upstream into the fork's branch, thrown away afterwards.
	git checkout --quiet --detach "$our_ref"
	if git merge --quiet --no-commit --no-ff "$up_ref" >/dev/null 2>&1; then
		echo "- **Merge** of upstream \`$up\` into \`$ours\`: clean." >>"$REPORT"
	else
		{
			echo "- **Merge** of upstream \`$up\` into \`$ours\`: conflicts in"
			conflicts
		} >>"$REPORT"
	fi
	git merge --abort 2>/dev/null || git reset --quiet --hard

	# A test rebase of the fork's own commits onto upstream. It stops at the
	# first commit that conflicts, so only that one is reported.
	git checkout --quiet --detach "$our_ref"
	if git rebase --quiet "$up_ref" >/dev/null 2>&1; then
		echo "- **Rebase** of \`$ours\`'s own commits onto upstream \`$up\`: clean." >>"$REPORT"
	else
		stopped=$(git rev-parse --short REBASE_HEAD 2>/dev/null || echo '?')
		{
			echo "- **Rebase** of \`$ours\`'s own commits onto upstream \`$up\`: stops at \`$stopped\` ($(git log -1 --format=%s REBASE_HEAD 2>/dev/null)), conflicts in"
			conflicts
		} >>"$REPORT"
		git rebase --abort
	fi
	echo >>"$REPORT"
done

git checkout --quiet --detach "${GITHUB_SHA:-HEAD}" 2>/dev/null || true

echo "changed=$changed"
[[ -n ${GITHUB_OUTPUT:-} ]] && echo "changed=$changed" >>"$GITHUB_OUTPUT"
exit 0
